/***************************************************************************
Do_Game () - The main game thing this is it dude
 ***************************************************************************/
BOOL           // TRUE=Aborted, FALSE = timeout
Do_Game (
VOID
)
{
   volatile INT  local_cnt;
   BOOL          b2_flag      = FALSE;
   BOOL          b3_flag      = FALSE;
   BOOL          init_flag    = TRUE;
   BOOL          rval         = FALSE;
   INT           start_score  = 0;

   draw_player = TRUE;

   srand ( ( 1024 * game_wave [ cur_game ] ) );

   fadeflag = FALSE;
   end_fadeflag = FALSE;
   KBD_Clear();
   IMS_StartAck();
   BUT_1 = FALSE;
   BUT_2 = FALSE;
   BUT_3 = FALSE;
   BUT_4 = FALSE;
  
   playerx = PLAYERINITX;
   playery = PLAYERINITY;
   PTR_SetPos ( playerx, playery );
   IPT_Start();

   RAP_GetShipPic();
   BONUS_Clear();
   ANIMS_Clear();
   SHOTS_Clear();
   ESHOT_Clear();

   memcpy ( gpal, palette, 768 );
   GFX_FadeOut ( 0, 0, 0, 2 );
  
   memset ( displaybuffer, 0, 64000 );
   memset ( displayscreen, 0, 64000 );

   local_cnt = FRAME_COUNT;
  
   g_flash = 0;
   g_oldsuper     = EMPTY;
   g_oldshield    = EMPTY;
   startendwave   = EMPTY;

   if ( demo_flag == DEMO_RECORD )
      DEMO_StartRec();

   // == CLEAR ALL BUTTONS ===========================

   start_score = plr.score;
   IMS_StartAck();
   memset ( buttons, 0, sizeof ( buttons ) );

   for (;;)
   {
      SHADOW_Clear();
  
      IPT_MovePlayer();
  
      if ( KBD_IsKey ( SC_F1 ) )
      {
         SWD_SetClearFlag ( FALSE );
         IPT_End();
         HELP_Win ( "OVERVW06_TXT" );
         memset ( displayscreen, 0, 64000 );
         IPT_Start();
         g_oldsuper = EMPTY;
         g_oldshield = EMPTY;
         RAP_ClearSides();
         RAP_DisplayStats();
         SWD_SetClearFlag ( TRUE );
         IMS_StartAck();
         BUT_1 = FALSE;
         BUT_2 = FALSE;
         BUT_3 = FALSE;
         BUT_4 = FALSE;
         b2_flag = FALSE;
         b3_flag = FALSE;
      }

      if ( KBD_IsKey ( SC_P ) )
      {
         while ( IMS_IsAck() );
         SWD_SetClearFlag ( FALSE );
         RAP_ClearSides();
         WIN_Pause();
         g_oldsuper = EMPTY;
         g_oldshield = EMPTY;
         RAP_ClearSides();
         RAP_DisplayStats();
         SWD_SetClearFlag ( TRUE );
         IMS_StartAck();
         BUT_1 = FALSE;
         BUT_2 = FALSE;
         BUT_3 = FALSE;
         BUT_4 = FALSE;
         b2_flag = FALSE;
         b3_flag = FALSE;
      }

      if ( KBD_IsKey ( SC_F8 ) && godmode )
      {
         while ( IMS_IsAck() );
         debugflag ^= TRUE;
      }

      if ( DEMO_Think() )
         break;

      if ( demo_mode  == DEMO_PLAYBACK )
      {
         if ( IMS_IsAck () && !BUT_2 && !BUT_3 && !BUT_4 )
         {
            rval = TRUE;
            break;
         }
      }

      switch ( KBD_LASTSCAN )
      {
         case SC_NONE:
            break;

         default:
            break;

         case SC_1:
            OBJS_MakeSpecial ( S_DUMB_MISSLE );
            break;

         case SC_2:
            OBJS_MakeSpecial ( S_MINI_GUN );
            break;

         case SC_3:
            OBJS_MakeSpecial ( S_TURRET );
            break;

         case SC_4:
            OBJS_MakeSpecial ( S_MISSLE_PODS );
            break;

         case SC_5:
            OBJS_MakeSpecial ( S_AIR_MISSLE  );
            break;

         case SC_6:
            OBJS_MakeSpecial ( S_GRD_MISSLE );
            break;

         case SC_7:
            OBJS_MakeSpecial ( S_BOMB );
            break;

         case SC_8:
            OBJS_MakeSpecial ( S_ENERGY_GRAB );
            break;

         case SC_9:
            OBJS_MakeSpecial ( S_PULSE_CANNON );
            break;

         case SC_0:
            OBJS_MakeSpecial ( S_DEATH_RAY );
            break;

         case SC_MINUS:
            OBJS_MakeSpecial ( S_FORWARD_LASER );
            break;
      }

      if ( BUT_1 )
      {
         OBJS_Use ( S_FORWARD_GUNS );
         OBJS_Use ( S_PLASMA_GUNS );
         OBJS_Use ( S_MICRO_MISSLE );
         BUT_1 = FALSE;
         if ( plr.sweapon != EMPTY )
            OBJS_Use ( plr.sweapon );
      }
  
      if ( BUT_2 )
      {
         BUT_2 = FALSE;
         if ( b2_flag == FALSE )
         {
            SND_Patch ( FX_SWEP, 127 );
            b2_flag = TRUE;
            OBJS_GetNext();
         }
      }
      else if ( b2_flag == TRUE )
      {
         b2_flag = FALSE;
      }
  
      if ( BUT_3 )
      {
         BUT_3 = FALSE;
         if ( b3_flag == FALSE )
         {
            b3_flag = TRUE;
            OBJS_Use ( S_MEGA_BOMB );
         }
      }
      else if ( b3_flag == TRUE )
      {
         b3_flag = FALSE;
      }

      if ( startendwave != EMPTY )
      {
         if ( startendwave == 0 )
         {
            end_wave = TRUE;   
         }

         startendwave--;
      }

      gl_cnt++;

      TILE_Think();
      ENEMY_Think();
      ESHOT_Think();
      BONUS_Think();
      SHOTS_Think();
      ANIMS_Think();
      OBJS_Think();
  
      if ( draw_player )
         SHADOW_Add ( curship [ playerpic + g_flash ], playerx , playery );
  
      TILE_Display();
      SHADOW_DisplayGround();
      ENEMY_DisplayGround();
      SHADOW_DisplaySky();
      ANIMS_DisplayGround();
  
      ENEMY_DisplaySky();
      SHOTS_Display();
      BONUS_Display();
      ANIMS_DisplaySky();

      if ( draw_player )
      {
         FLAME_Down ( player_cx + -o_engine[ playerpic ] - 3, player_cy + 15, 4, gl_cnt % 2 ); 
         FLAME_Down ( player_cx + o_engine[ playerpic ] - 2, player_cy + 15, 4, gl_cnt % 2 ); 
         GFX_PutSprite ( GLB_GetItem ( curship [ playerpic + g_flash ] ), playerx , playery );
         g_flash = 0;
      }

      ANIMS_DisplayHigh();
      ESHOT_Display();
  
      if ( fadeflag )
      {
         if ( fadecnt >= FADE_FRAMES - 1 )
         {
            RAP_ClearSides();
            g_mapleft = MAP_LEFT;
            GFX_SetPalette ( gpal, 0 );
            fadeflag = FALSE;
            g_oldsuper = EMPTY;
            g_oldshield = EMPTY;
         }
         else
         {
            RAP_ClearSides();
            GFX_SetRetraceFlag ( TRUE );
            GFX_FadeFrame ( gpal, fadecnt, FADE_FRAMES );
            GFX_SetRetraceFlag ( FALSE );
            g_mapleft = MAP_LEFT + shakes [ fadecnt ];
            fadecnt++;
         }
      }
      else
      {
         if ( !init_flag )
            RAP_PaletteStuff();
      }

      RAP_DisplayStats();

      while ( FRAME_COUNT - local_cnt < 3 );
      local_cnt = FRAME_COUNT;

      if ( fadeflag )
         TILE_ShakeScreen();
      else
         TILE_DisplayScreen();

      if ( startfadeflag )
      {
         SND_Patch ( FX_GEXPLO, 127 );
         SND_Patch ( FX_AIREXPLO, 127 );
         GFX_SetRetraceFlag ( TRUE );
         GFX_FadeOut ( 63, 60, 60, 1 );
         GFX_FadeStart();
         startfadeflag = FALSE;
         fadeflag = TRUE;
         fadecnt = 0;
         GFX_SetRetraceFlag ( FALSE );
      }

