VOID
RAP_Bday (
VOID
)
{
   struct dosdate_t date;
   INT loop;

   bday_flag = FALSE;
   bday_num  = EMPTY;

   _dos_getdate ( &date );

   for ( loop = 0; loop < MAX_BDAY; loop++ )
   {
      if ( bday [ loop ]. day == 0 ) continue;

      if ( date.month == bday [ loop ].month &&
           date.day == bday [ loop ].day
         && date.year >= bday [ loop ].year )
      {
         bday_num = loop;
         if ( loop == 0 )
            bday_flag = TRUE;
         break;
      }
   }
}


BOOL
RAP_IsDate (
VOID
)
{
   struct dosdate_t date;
   INT comp1;
   INT comp2;
   INT num;

   _dos_getdate ( &date );

   if ( date.year != YEAR )
      return ( FALSE );

   comp1 = date.month;
   comp1 = comp1 << 5;
   comp1 += date.day;

   comp2 = MONTH;
   comp2 = comp2 << 5;
   comp2 += DAY;

   num = comp1 - comp2;

   if ( num >= 0 && num <= WLENGTH )
      return ( TRUE );

   return ( FALSE );
}

