 ***************************************************************************/
VOID
INTRO_EndGame (
INT game
)
{
   IMS_StartAck();

   if ( !gameflag[game] )
      return;

   if ( game > 2 )
      game = 2;

   while ( IMS_IsAck() );
   IMS_StartAck();

   switch ( game )
   {
      default:
      case 0:
         INTRO_Game1End();
         break;

      case 1:
         INTRO_Game2End();
         break;

      case 2:
         INTRO_Game3End();
         break;
   }

