   OBJS_Add ( S_ENERGY );
   OBJS_Add ( S_ENERGY );
   OBJS_Add ( S_ENERGY );
   OBJS_Add ( S_DETECT );
   plr.score = 10000;

   switch ( game )
   {
      default:
         OBJS_Add ( S_MICRO_MISSLE );
         OBJS_Add ( S_MEGA_BOMB );
         OBJS_Add ( S_MINI_GUN );
         OBJS_Add ( S_AIR_MISSLE );
         OBJS_Add ( S_TURRET );
         OBJS_Add ( S_DEATH_RAY );
         break;

      case  1:
         OBJS_Add ( S_MEGA_BOMB );
