         OBJS_Add ( S_PLASMA_GUNS );
         OBJS_Add ( S_MICRO_MISSLE );
         OBJS_Add ( S_TURRET );
         OBJS_Add ( S_GRD_MISSLE );
         plr.score += 327683;
         break;

      case  2:
         OBJS_Add ( S_MEGA_BOMB );
