      if ( !spriteflag [2] && !spriteflag [3] )
         EXIT_Error ("ENEMY_LoadSprites() - F:%d  G1:%d G2:%d G3:%d G4:%d", g_numslibs, spriteflag[0], spriteflag[1], spriteflag[2], spriteflag[3] );
