   for ( loop = 0; loop < 4; loop++ )
   {
      if ( spriteflag [ loop ] )
      {
         slib [ loop ] = ( SPRITE * ) GLB_LockItem ( spriteitm [ loop ] );

         if ( slib [ loop ] == NUL )
            EXIT_Error("ENEMY_LoadSprites() - memory");

         numslib [ loop ] = GLB_ItemSize ( spriteitm [ loop ] );
         numslib [ loop ] = numslib [ loop ] / sizeof ( SPRITE );
      }
   }
}

