BOOL
ENEMY_DamageAll (
INT x,                     // INPUT : x position
INT y,                     // INPUT : y position
INT damage                 // INPUT : damage
)
{
   INT loop;
   SPRITE_SHIP * cur;

   for ( loop = 0; loop < cur_visable; loop++ )
